-- =============================================================================================
-- Hand-written below this line: allowed types and sizes, a server-chosen key inside the
-- tenant's prefix, at most 10 live attachments per request or work order, attachments only on
-- live requests and uncancelled work, a work order's attachment filed under its request, the
-- lifecycle PENDING -> READY | REJECTED and READY -> removed (once), row-level security and
-- grants. See docs/architecture/DATA_MODEL.md section 7 (Maintenance).
-- =============================================================================================

ALTER TABLE "maintenance_attachments" ADD CONSTRAINT "maintenance_attachments_target"
  CHECK (num_nonnulls("request_id", "work_order_id") >= 1);
ALTER TABLE "maintenance_attachments" ADD CONSTRAINT "maintenance_attachments_type"
  CHECK ("content_type" IN ('image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf'));
-- 10 MB at most.
ALTER TABLE "maintenance_attachments" ADD CONSTRAINT "maintenance_attachments_size"
  CHECK ("size_bytes" BETWEEN 1 AND 10485760);
ALTER TABLE "maintenance_attachments" ADD CONSTRAINT "maintenance_attachments_file_name"
  CHECK ("file_name" = btrim("file_name") AND length("file_name") BETWEEN 1 AND 200
         AND "file_name" !~ '[/\\"<>|*?:[:cntrl:]]');
-- Keys live under the tenant's own prefix: org/<organisation>/prop/<property>/maintenance/<id>.
ALTER TABLE "maintenance_attachments" ADD CONSTRAINT "maintenance_attachments_key"
  CHECK ("storage_key" = 'org/' || "organisation_id" || '/prop/' || "property_id" || '/maintenance/' || "id");
ALTER TABLE "maintenance_attachments" ADD CONSTRAINT "maintenance_attachments_lifecycle"
  CHECK (("status" = 'READY') = ("ready_at" IS NOT NULL)
         AND ("removed_at" IS NULL) = ("removed_by_user_id" IS NULL)
         AND ("removed_at" IS NULL OR "status" = 'READY'));

CREATE FUNCTION app_maintenance_attachment_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  wo record;
  live integer;
BEGIN
  IF NEW."status" <> 'PENDING' OR NEW."removed_at" IS NOT NULL THEN
    RAISE EXCEPTION 'attachments start pending' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."work_order_id" IS NOT NULL THEN
    SELECT "request_id", "status" INTO wo FROM "work_orders" WHERE "id" = NEW."work_order_id";
    IF wo."status" = 'CANCELLED' THEN
      RAISE EXCEPTION 'cancelled work takes no attachments' USING ERRCODE = 'check_violation';
    END IF;
    -- Filed under the work order's request too, so the requester can see resident-visible ones.
    IF NEW."request_id" IS NULL THEN
      NEW."request_id" := wo."request_id";
    ELSIF NEW."request_id" IS DISTINCT FROM wo."request_id" THEN
      RAISE EXCEPTION 'a work order''s attachment belongs to that work order''s request'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW."visibility" = 'RESIDENT' AND NEW."request_id" IS NULL THEN
    RAISE EXCEPTION 'work without a request has no resident to show an attachment to'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."request_id" IS NOT NULL AND EXISTS (
       SELECT 1 FROM "maintenance_requests" WHERE "id" = NEW."request_id" AND "status" IN ('CLOSED', 'REJECTED', 'CANCELLED')) THEN
    RAISE EXCEPTION 'a finished request takes no attachments' USING ERRCODE = 'check_violation';
  END IF;
  -- At most 10 not removed and not rejected, per work order, or per request for its own ones.
  IF NEW."work_order_id" IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.attachments:' || NEW."work_order_id"::text, 0));
    SELECT count(*) INTO live FROM "maintenance_attachments"
     WHERE "work_order_id" = NEW."work_order_id" AND "status" <> 'REJECTED' AND "removed_at" IS NULL;
  ELSE
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.attachments:' || NEW."request_id"::text, 0));
    SELECT count(*) INTO live FROM "maintenance_attachments"
     WHERE "request_id" = NEW."request_id" AND "work_order_id" IS NULL
       AND "status" <> 'REJECTED' AND "removed_at" IS NULL;
  END IF;
  IF live >= 10 THEN
    RAISE EXCEPTION 'at most 10 attachments' USING ERRCODE = 'check_violation';
  END IF;
  NEW."created_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "maintenance_attachments_insert"
  BEFORE INSERT ON "maintenance_attachments"
  FOR EACH ROW EXECUTE FUNCTION app_maintenance_attachment_insert();

-- Checked once (PENDING -> READY or REJECTED), removed once (READY -> removed); nothing else changes.
CREATE FUNCTION app_maintenance_attachment_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF (NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."work_order_id", NEW."storage_key",
      NEW."file_name", NEW."content_type", NEW."size_bytes", NEW."kind", NEW."visibility",
      NEW."uploaded_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."request_id", OLD."work_order_id", OLD."storage_key",
      OLD."file_name", OLD."content_type", OLD."size_bytes", OLD."kind", OLD."visibility",
      OLD."uploaded_by_user_id", OLD."created_at")
     OR NOT (
       (OLD."status" = 'PENDING' AND NEW."status" IN ('READY', 'REJECTED') AND NEW."removed_at" IS NULL)
       OR (OLD."status" = 'READY' AND NEW."status" = 'READY' AND OLD."removed_at" IS NULL
           AND NEW."removed_at" IS NOT NULL AND NEW."ready_at" = OLD."ready_at")
     ) THEN
    RAISE EXCEPTION 'attachment % is checked once and removed once; nothing else changes', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."status" = 'PENDING' THEN
    NEW."ready_at" := CASE WHEN NEW."status" = 'READY' THEN now() END;
  ELSE
    NEW."removed_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "maintenance_attachments_guard"
  BEFORE UPDATE ON "maintenance_attachments"
  FOR EACH ROW EXECUTE FUNCTION app_maintenance_attachment_guard();

ALTER TABLE "maintenance_attachments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "maintenance_attachments" FORCE ROW LEVEL SECURITY;
CREATE POLICY "maintenance_attachments_select" ON "maintenance_attachments" FOR SELECT
  USING (organisation_id = app_current_organisation_id());
CREATE POLICY "maintenance_attachments_insert" ON "maintenance_attachments" FOR INSERT
  WITH CHECK (organisation_id = app_current_organisation_id());
CREATE POLICY "maintenance_attachments_update" ON "maintenance_attachments" FOR UPDATE
  USING (organisation_id = app_current_organisation_id())
  WITH CHECK (organisation_id = app_current_organisation_id());

REVOKE ALL ON "maintenance_attachments" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "maintenance_attachments" TO veyra_app;
